import{_ as i,o as a,c as e,ae as l}from"./chunks/framework.CK6jtcgr.js";const p=JSON.parse('{"title":"Digital Trust and Capability Routing","description":"","frontmatter":{},"headers":[],"relativePath":"guide/digital-trust-and-capability-routing.md","filePath":"guide/digital-trust-and-capability-routing.md"}'),r={name:"guide/digital-trust-and-capability-routing.md"};function o(n,t,d,s,c,u){return a(),e("div",null,[...t[0]||(t[0]=[l('<h1 id="digital-trust-and-capability-routing" tabindex="-1">Digital Trust and Capability Routing <a class="header-anchor" href="#digital-trust-and-capability-routing" aria-label="Permalink to &quot;Digital Trust and Capability Routing&quot;">​</a></h1><p>The <code>.digital</code> surface is not only about presentation. It is about trusted digital presence tied to identity, capability, and recovery.</p><h2 id="digital-trust-model" tabindex="-1">Digital trust model <a class="header-anchor" href="#digital-trust-model" aria-label="Permalink to &quot;Digital trust model&quot;">​</a></h2><p>Digital trust includes:</p><ul><li>identity legibility</li><li>reputation and continuity</li><li>privacy-aware visibility</li><li>traceable capability attachment</li><li>recoverable connection states</li></ul><h2 id="capability-routing" tabindex="-1">Capability routing <a class="header-anchor" href="#capability-routing" aria-label="Permalink to &quot;Capability routing&quot;">​</a></h2><p>Digital surfaces connect directly to the auth and connections story.</p><p>A public-facing digital surface can route users toward:</p><ul><li>platform sign-in</li><li>provider connection state</li><li>capability health</li><li>recovery and degraded-state handling</li></ul><h2 id="why-this-matters" tabindex="-1">Why this matters <a class="header-anchor" href="#why-this-matters" aria-label="Permalink to &quot;Why this matters&quot;">​</a></h2><p>A digital presence without governed capability routing is just branding.</p><p>SocioProphet treats digital trust as the connection between:</p><ul><li>who the user is</li><li>what they are allowed to do</li><li>what capabilities are connected</li><li>how failure is handled</li></ul><h2 id="related-docs" tabindex="-1">Related docs <a class="header-anchor" href="#related-docs" aria-label="Permalink to &quot;Related docs&quot;">​</a></h2><ul><li><a href="https://socioprophet.com/documentation/auth-and-connections/" target="_blank" rel="noreferrer">Auth and Connections</a></li><li><a href="https://socioprophet.com/documentation/provider-capability-routing/" target="_blank" rel="noreferrer">Provider Capability Routing</a></li><li><a href="https://socioprophet.com/documentation/auth-recovery-and-connection-health/" target="_blank" rel="noreferrer">Auth Recovery and Connection Health</a></li></ul>',15)])])}const g=i(r,[["render",o]]);export{p as __pageData,g as default};
